#!/usr/bin/env bash
# wake-codex.sh — start a headless Codex turn for one handoff.
# Generated by `install.sh --target codex`.
#
#   wake-codex.sh "<handoff>"            # a fresh non-interactive turn
#   wake-codex.sh "<handoff>" <sid>      # resume thread <sid>
#
# A worker must run in the card's project directory, and only this host-local
# glue can resolve it. Inputs (set by the supervisor):
#   TP_PROJECT        the card's board project identity
#   TP_PROJECTS_JSON  the local project map (default: beside the installed skill)
#   TP_NODE           node used to resolve it (default: `node` on PATH)
# If the directory cannot be resolved, exit 3 without starting a worker.
#
# Do not default to bypassing approvals or the sandbox. Run under the
# non-interactive sandbox / approval policy; a bypass needs written
# authorization, documented here.
set -eu

prompt="${1:-}"
sid="${2:-}"

if [ -z "$prompt" ]; then
  echo "wake-codex: a handoff prompt is required" >&2
  exit 2
fi

projects_json="${TP_PROJECTS_JSON:-$(dirname "$0")/../skills/meerkat-taskpanel/projects.json}"
if ! cwd="$("${TP_NODE:-node}" "{{LOOP}}/scripts/wake-cwd.mjs" --project "${TP_PROJECT:-}" --projects-json "$projects_json")"; then
  echo "wake-codex: refusing to wake a worker without a target directory" >&2
  exit 3
fi
# `if !` cannot catch an empty $cwd: `cd ""` succeeds in bash and would run the
# worker in the caller's directory. The absolute-path test covers empty and relative.
case "$cwd" in
  /*) ;;
  *) echo "wake-codex: refusing to wake a worker without a target directory" >&2; exit 3 ;;
esac
cd "$cwd"
echo "wake-codex: working directory $cwd" >&2

if [ -n "$sid" ]; then
  exec codex exec resume "$sid" "$prompt"
fi

exec codex exec "$prompt"
